RSpec.describe "Timekeeping handoff load with a tampered checkpoint" do
  include_context "timekeeping entry writes without transactional fixtures"

  let(:tampered_load_token) { "service-#{SecureRandom.hex(24)}" }
  let(:tampered_load_auth) { { "Authorization" => "Bearer #{tampered_load_token}" } }

  around do |example|
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => tampered_load_token
    ) { example.run }
  end

  def tampered_load_table_rows
    %w[entries reservations invoice_operations audit_events idempotency_receipts].index_with do |table|
      ApplicationRecord.connection.select_rows("SELECT * FROM #{table} ORDER BY 1, 2")
    end
  end

  def tampered_load_entry(note)
    Entry.create!(company_id: 1, user_id: 7, project_id: 3, work_date: "2026-03-02", duration: 90.0,
                  note:, bill_status: "unbilled", source: "manual", source_metadata: {})
  end

  # "Recompute the digest inside the transaction and roll back on a mismatch."
  # Acceptance: "Timekeeping's load replaces its tables in one transaction".
  it "refuses a checkpoint whose rows no longer match its digest and leaves every handoff table as it was" do
    entry = tampered_load_entry("Design review")
    AuditEvent.create!(company_id: 1, entry_id: entry.id, actor_type: "user", actor_id: 7, action: "create",
                       before: nil, after: { "note" => "Design review" }, entry_created_at: entry.created_at,
                       created_at: Time.current)
    Timekeeping::Admission.fence!

    get "/internal/v1/handoff/checkpoint", headers: tampered_load_auth
    expect(response.status).to eq(200)
    document = JSON.parse(response.body)
    note = document.fetch("tables").fetch("entries").first.find { |column, _| column == "note" }
    note[1] = ["str", "tampered after the digest was written"]

    # Written after the export: a load that deleted before failing and kept
    # the delete would lose this row.
    tampered_load_entry("Written after export")
    before = tampered_load_table_rows

    put "/internal/v1/handoff/checkpoint", params: JSON.generate(document),
                                           headers: tampered_load_auth.merge("Content-Type" => "application/json")

    expect([response.status, response.parsed_body]).to eq([409, { "reason" => "handoff_refused" }])
    expect(tampered_load_table_rows).to eq(before)
  end
end

