      Timekeeping::Environment::SERVICE_TOKEN => open_load_token
    ) { example.run }
  end

  def open_load_entry(note)
    Entry.create!(company_id: 1, user_id: 7, project_id: 3, work_date: "2026-03-02", duration: 90.0,
                  note:, bill_status: "unbilled", source: "manual", source_metadata: {})
  end

  # The plan's added guard: a load runs only while admission is fenced, because
  # replacing the tables deletes every row the checkpoint lacks, such as an
  # entry written after the export.
  it "refuses a load while Timekeeping still admits entry writes and keeps an entry written after the export" do
    Timekeeping::Admission.ensure_initial!
    Timekeeping::Admission.admit!(generation: 1)
    open_load_entry("Design review")

    get "/internal/v1/handoff/checkpoint", headers: open_load_auth
    expect(response.status).to eq(200)
    checkpoint = response.body
    late_entry = open_load_entry("Written after export")

    put "/internal/v1/handoff/checkpoint", params: checkpoint,
                                           headers: open_load_auth.merge("Content-Type" => "application/json")

    expect([response.status, response.parsed_body]).to eq([409, { "reason" => "handoff_refused" }])
    expect(Entry.exists?(late_entry.id)).to be(true)
    expect(Entry.count).to eq(2)
  end
end

