  let(:admit_token) { "service-#{SecureRandom.hex(24)}" }
  let(:admit_auth) { { "Authorization" => "Bearer #{admit_token}" } }

  around do |example|
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => admit_token
    ) { example.run }
  end

  # "Admission: fence and admit through `Timekeeping::Admission.fence!` and
  # `Timekeeping::Admission.admit!`, from the admission-fence work this depends
  # on. This endpoint only calls them."
  # A refused admit must never answer success, or the caller would believe
  # writes are admitted while Timekeeping is still fenced.
  it "refuses to admit a generation sent as a string and leaves Timekeeping fenced" do
    post "/internal/v1/handoff/admission/fence", headers: admit_auth, as: :json
    expect(response.status).to eq(200)

    ["3", 0].each do |generation|
      post "/internal/v1/handoff/admission/admit", params: { generation: }, headers: admit_auth, as: :json

      expect([response.status, response.parsed_body]).to eq([400, { "reason" => "invalid_request" }])
      expect(Timekeeping::Admission.current.generation).to be_nil
    end
  end
end
